# A fixed PowerShell engine included in the AI handoff document.
# Only the JSON map between the AI RULES markers is editable.
from __future__ import annotations
import hashlib

_PS1_SOURCE = "#Requires -Version 5.1\n# PlayDock name-only renamer. No Python or AI API needed.\n# AI MUST REPLACE ONLY the JSON array inside the rules; do not modify engine code.\nparam(\n    [ValidateSet('Menu', 'Preview', 'Apply', 'Undo')]\n    [string] $Mode = 'Menu',\n    [string] $Folder = ''\n)\n$ErrorActionPreference = 'Stop'\n\n# Independent scanner EXE can also verify the code against its built-in template.\n# This self-check detects accidental AI edits outside the JSON rules.\n$ExpectedTemplateHash = '__PLAYDOCK_HASH__'\nfunction Assert-TemplateIntegrity {\n    $source = [IO.File]::ReadAllText($PSCommandPath, [Text.Encoding]::UTF8)\n    $source = $source.Replace(([string][char]13 + [char]10), [string][char]10)\n    $source = $source.Replace([string][char]13, [string][char]10)\n    $head = '$renameJson = @' + [char]39 + [char]10\n    $tail = [string][char]10 + [char]39 + '@'\n    $start = $source.IndexOf($head, [StringComparison]::Ordinal)\n    if ($start -lt 0 -or $source.IndexOf($head, $start + $head.Length, [StringComparison]::Ordinal) -ge 0) {\n        throw 'AI 변경 데이터 영역이 없거나 중복되었습니다. 실행을 중단합니다.'\n    }\n    $begin = $start + $head.Length\n    $stop = $source.IndexOf($tail, $begin, [StringComparison]::Ordinal)\n    if ($stop -lt 0 -or $source.IndexOf($tail, $stop + $tail.Length, [StringComparison]::Ordinal) -ge 0) {\n        throw 'AI 변경 데이터 영역이 손상되었습니다. 실행을 중단합니다.'\n    }\n    $canonical = $source.Substring(0, $begin) + '[]' + $source.Substring($stop)\n    $canonical = $canonical.Replace($ExpectedTemplateHash, ('0' * 64))\n    $sha = [Security.Cryptography.SHA256]::Create()\n    try {\n        $sum = [BitConverter]::ToString($sha.ComputeHash([Text.Encoding]::UTF8.GetBytes($canonical))).Replace('-', '').ToLowerInvariant()\n    } finally { $sha.Dispose() }\n    if ($sum -cne $ExpectedTemplateHash) {\n        throw 'PowerShell 기본 코드가 변경됐습니다. AI는 JSON 이름 목록만 수정해야 합니다. 실행을 중단합니다.'\n    }\n}\nAssert-TemplateIntegrity\n\n# Read-only Windows file identity: volume ID + file index, without reading archive content.\nAdd-Type -TypeDefinition @'\nusing System;\nusing System.IO;\nusing System.ComponentModel;\nusing System.Runtime.InteropServices;\nusing Microsoft.Win32.SafeHandles;\n[StructLayout(LayoutKind.Sequential)]\npublic struct PlayDockFileInformation {\n    public uint Attributes;\n    public long CreationTime;\n    public long LastAccessTime;\n    public long LastWriteTime;\n    public uint VolumeSerialNumber;\n    public uint FileSizeHigh;\n    public uint FileSizeLow;\n    public uint NumberOfLinks;\n    public uint FileIndexHigh;\n    public uint FileIndexLow;\n}\npublic static class PlayDockFileId {\n    [DllImport(\"kernel32.dll\", SetLastError = true)]\n    public static extern bool GetFileInformationByHandle(SafeFileHandle handle, out PlayDockFileInformation data);\n    public static string Identify(string path) {\n        using (var file = new FileStream(path, FileMode.Open, FileAccess.Read,\n                         FileShare.ReadWrite | FileShare.Delete)) {\n            PlayDockFileInformation info;\n            if (!GetFileInformationByHandle(file.SafeFileHandle, out info))\n                throw new Win32Exception(Marshal.GetLastWin32Error());\n            return info.VolumeSerialNumber.ToString(\"X8\") + \":\" +\n                   info.FileIndexHigh.ToString(\"X8\") + info.FileIndexLow.ToString(\"X8\");\n        }\n    }\n}\n'@\n\n# ===== BEGIN AI RULES (official_confirmed only) =====\n# JSON data only: [{\"OldName\":\"...zip\",\"NewName\":\"...zip\"}, ...]\n$renameJson = @'\n[]\n'@\n# ===== END AI RULES =====\n$renameRules = @($renameJson | ConvertFrom-Json -ErrorAction Stop)\n\nfunction Select-GameFolder {\n    try {\n        Add-Type -AssemblyName System.Windows.Forms -ErrorAction Stop\n        $dialog = New-Object System.Windows.Forms.FolderBrowserDialog\n        $dialog.Description = '게임 압축파일이 있는 폴더를 선택하세요.'\n        $dialog.ShowNewFolderButton = $false\n        try {\n            if ($dialog.ShowDialog() -ne [System.Windows.Forms.DialogResult]::OK) { return '' }\n            return $dialog.SelectedPath\n        } finally { $dialog.Dispose() }\n    } catch {\n        return (Read-Host '게임 압축파일 폴더 전체 경로')\n    }\n}\n\nfunction Assert-ArchiveName([string] $Name) {\n    if ([string]::IsNullOrWhiteSpace($Name) -or $Name -match '[<>:\"/\\\\|?*\\x00-\\x1f]' -or\n        $Name.EndsWith(' ') -or $Name.EndsWith('.') -or\n        $Name -cne [IO.Path]::GetFileName($Name)) {\n        throw \"파일 이름 형식이 잘못되었습니다: $Name\"\n    }\n    $stem = [IO.Path]::GetFileNameWithoutExtension($Name)\n    if ($stem -match '^(?i:CON|PRN|AUX|NUL|COM[1-9]|LPT[1-9])(?:\\..*)?$') {\n        throw \"Windows 예약 파일명은 사용할 수 없습니다: $Name\"\n    }\n    if ([IO.Path]::GetExtension($Name).ToLowerInvariant() -notin @('.zip','.7z','.rar')) {\n        throw \"ZIP / 7z / RAR 확장자만 변경 가능합니다: $Name\"\n    }\n}\n\nfunction Get-ArchiveFiles([string] $Root) {\n    $found = New-Object System.Collections.ArrayList\n    $stack = New-Object 'System.Collections.Generic.Stack[string]'\n    $stack.Push($Root)\n    while ($stack.Count -gt 0) {\n        $current = $stack.Pop()\n        foreach ($entry in [IO.DirectoryInfo]::new($current).EnumerateFileSystemInfos()) {\n            if (($entry.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0) { continue }\n            if ($entry -is [IO.DirectoryInfo]) {\n                $stack.Push($entry.FullName)\n            } elseif ($entry -is [IO.FileInfo]) {\n                if ($entry.Extension.ToLowerInvariant() -in @('.zip','.7z','.rar')) {\n                    [void] $found.Add($entry)\n                }\n            }\n        }\n    }\n    return ,($found.ToArray())\n}\n\nfunction Safe-Path([string] $Base, [string] $RelativeDir, [string] $FileName) {\n    Assert-ArchiveName $FileName\n    $here = $Base\n    if ($RelativeDir) {\n        foreach ($part in ($RelativeDir -split '[\\\\/]')) {\n            if (-not $part -or $part -eq '.' -or $part -eq '..' -or $part -match '[:*?\"<>|]') {\n                throw '변경 이력에 잘못된 상대 폴더가 있습니다.'\n            }\n            $here = Join-Path $here $part\n            $dirItem = Get-Item -LiteralPath $here -ErrorAction Stop\n            if (($dirItem.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0 -or\n                -not $dirItem.PSIsContainer) {\n                throw \"연결 폴더는 사용할 수 없습니다: $here\"\n            }\n        }\n    }\n    return (Join-Path $here $FileName)\n}\n\nfunction Save-Journal($Journal, [string] $JournalPath) {\n    $tmp = \"$JournalPath.tmp\"\n    $Journal | ConvertTo-Json -Depth 6 | Set-Content -LiteralPath $tmp -Encoding UTF8\n    Move-Item -LiteralPath $tmp -Destination $JournalPath -Force\n}\n\nfunction Undo-Last([string] $Root, [string] $HistoryDir) {\n    if (-not (Test-Path -LiteralPath $HistoryDir -PathType Container)) {\n        Write-Host '되돌릴 변경 기록이 없습니다.'; return\n    }\n    $journalFile = $null\n    $journal = $null\n    foreach ($log in (Get-ChildItem -LiteralPath $HistoryDir -Filter '*.json' -File |\n                         Sort-Object LastWriteTimeUtc -Descending)) {\n        try { $candidate = Get-Content -LiteralPath $log.FullName -Raw -Encoding UTF8 | ConvertFrom-Json }\n        catch { continue }\n        if ($candidate.Folder -ieq $Root -and -not $candidate.Undone -and\n            @($candidate.Records).Count -gt 0) {\n            $journalFile = $log.FullName; $journal = $candidate; break\n        }\n    }\n    if (-not $journalFile) { Write-Host '이 폴더에서 되돌릴 최근 작업이 없습니다.'; return }\n    Write-Host \"되돌릴 작업: $($journal.Records.Count)건\"\n    foreach ($row in $journal.Records) {\n        Write-Host \"  $($row.NewName) -> $($row.OldName)\"\n    }\n    if ((Read-Host '되돌리려면 UNDO 입력') -cne 'UNDO') { Write-Host '취소됨'; return }\n    $errors = 0\n    for ($i = $journal.Records.Count - 1; $i -ge 0; $i--) {\n        $row = $journal.Records[$i]\n        try {\n            $old = Safe-Path $Root $row.RelativeDir $row.OldName\n            $new = Safe-Path $Root $row.RelativeDir $row.NewName\n            $oldExists = Test-Path -LiteralPath $old\n            $newExists = Test-Path -LiteralPath $new\n            if ($oldExists -and -not $newExists) { $row.State = 'undone'; continue }\n            if (-not $newExists -or $oldExists) {\n                throw '이름 충돌 또는 파일 누락; 안전하게 건너뜁니다.'\n            }\n            $item = Get-Item -LiteralPath $new\n            if ($item.PSIsContainer -or ($item.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0) {\n                throw '파일이 아니거나 링크입니다.'\n            }\n            # Reject stale or legacy journals: a filename alone cannot identify a file.\n            if ($null -eq $row.Length -or $null -eq $row.LastWriteUtcTicks -or\n                $null -eq $row.CreationUtcTicks -or [string]::IsNullOrWhiteSpace($row.FileId)) {\n                throw '안전한 파일 동일성 정보가 없는 변경 기록입니다. 자동 복구하지 않습니다.'\n            }\n            if ([long]$item.Length -ne [long]$row.Length -or\n                [long]$item.LastWriteTimeUtc.Ticks -ne [long]$row.LastWriteUtcTicks -or\n                [long]$item.CreationTimeUtc.Ticks -ne [long]$row.CreationUtcTicks -or\n                [PlayDockFileId]::Identify($new) -cne [string]$row.FileId) {\n                throw '변경 후 파일이 교체·수정된 것으로 판단됩니다. 복구를 건너뜁니다.'\n            }\n            Rename-Item -LiteralPath $new -NewName $row.OldName -ErrorAction Stop\n            $row.State = 'undone'\n            Write-Host \"복구: $($row.NewName) -> $($row.OldName)\"\n        } catch {\n            $errors++\n            Write-Warning \"복구 실패: $($row.NewName): $_\"\n        }\n        Save-Journal $journal $journalFile\n    }\n    if ($errors -eq 0) { $journal.Undone = $true; Save-Journal $journal $journalFile }\n    Write-Host \"되돌리기 종료 (실패: $errors건)\"\n}\n\nif (-not $Folder) { $Folder = Select-GameFolder }\nif (-not $Folder -or -not (Test-Path -LiteralPath $Folder -PathType Container)) {\n    Write-Host '게임 폴더가 선택되지 않았습니다.'; exit 1\n}\n$Root = [IO.Path]::GetFullPath((Get-Item -LiteralPath $Folder).FullName)\nif ($Root -ne [IO.Path]::GetPathRoot($Root)) { $Root = $Root.TrimEnd('\\') }\n$rootItem = Get-Item -LiteralPath $Root\nif (($rootItem.Attributes -band [IO.FileAttributes]::ReparsePoint) -ne 0) {\n    throw '연결 폴더는 대상이 될 수 없습니다.'\n}\nWrite-Host \"선택한 게임 폴더: $Root\"\nif ((Read-Host '이 폴더가 맞습니까? 맞으면 Y, 아니면 Enter를 누르세요') -cne 'Y') {\n    Write-Host '폴더가 확인되지 않았으므로 아무 작업도 하지 않았습니다.'\n    exit 0\n}\n$HistoryDir = if ($env:PLAYDOCK_RENAME_HISTORY_DIR) { $env:PLAYDOCK_RENAME_HISTORY_DIR } else {\n    Join-Path $env:LOCALAPPDATA 'PlayDock\\RenameHistory'\n}\nif ($Mode -eq 'Menu') {\n    Write-Host \"선택한 폴더: $Root\"\n    Write-Host '[1] 변경 미리보기  [2] 실제 이름 변경  [3] 최근 변경 되돌리기'\n    $answer = Read-Host '번호를 입력하세요'\n    $Mode = switch ($answer) { '1' {'Preview'} '2' {'Apply'} '3' {'Undo'} default {'Preview'} }\n}\nif ($Mode -eq 'Undo') { Undo-Last $Root $HistoryDir; exit 0 }\nif (@($renameRules).Count -eq 0) { Write-Host 'AI가 작성한 이름 변경 목록이 없습니다.'; exit 0 }\n\n$byName = @{}\nforeach ($file in (Get-ArchiveFiles $Root)) {\n    if (-not $byName.ContainsKey($file.Name)) { $byName[$file.Name] = @() }\n    $byName[$file.Name] += $file\n}\n$plans = New-Object System.Collections.ArrayList\n$errors = New-Object System.Collections.ArrayList\n$seenOld = @{}; $seenNew = @{}\nforeach ($rule in $renameRules) {\n    $oldName = [string] $rule.OldName\n    $newName = [string] $rule.NewName\n    try {\n        Assert-ArchiveName $oldName\n        Assert-ArchiveName $newName\n        if ([IO.Path]::GetExtension($oldName) -ine [IO.Path]::GetExtension($newName)) {\n            throw '확장자 변경은 허용하지 않습니다.'\n        }\n        if ($seenOld.ContainsKey($oldName)) { throw '변경 목록의 원본 이름이 중복됐습니다.' }\n        $seenOld[$oldName] = $true\n        if (-not $byName.ContainsKey($oldName)) { throw '선택한 폴더에 정확히 같은 원본 파일명이 없습니다.' }\n        $matches = @($byName[$oldName])\n        if ($matches.Count -ne 1) { throw '하위 폴더에 동일한 이름의 파일이 여러 개 있습니다.' }\n        $file = $matches[0]\n        if ($file.Name -ceq $newName) { continue }\n        $target = Join-Path $file.DirectoryName $newName\n        if ($seenNew.ContainsKey($target)) { throw '새 이름이 다른 변경 규칙과 중복됐습니다.' }\n        $seenNew[$target] = $true\n        if ((Test-Path -LiteralPath $target) -and $target -ine $file.FullName) {\n            throw '새 이름으로 된 파일 또는 폴더가 이미 존재합니다.'\n        }\n        $relDir = $file.DirectoryName.Substring($Root.Length).TrimStart('\\')\n        [void] $plans.Add([pscustomobject]@{\n            File=$file; Target=$target; RelativeDir=$relDir; NewName=$newName;\n            Length=$file.Length; ChangedUtc=$file.LastWriteTimeUtc.Ticks\n        })\n    } catch { [void] $errors.Add(\"$oldName -> $newName : $_\") }\n}\nWrite-Host \"대상 폴더: $Root\"\nWrite-Host \"변경 예정: $($plans.Count)건 / 규칙: $(@($renameRules).Count)건 / 오류: $($errors.Count)건\"\nforeach ($row in $plans) { Write-Host \"  $($row.File.Name) -> $($row.NewName)\" }\nforeach ($message in $errors) { Write-Warning $message }\nif ($errors.Count -gt 0) { Write-Host '오류가 있어 아무 파일도 변경하지 않았습니다.'; exit 1 }\nif ($Mode -eq 'Preview' -or $plans.Count -eq 0) { Write-Host '미리보기 완료. 파일은 변경하지 않았습니다.'; exit 0 }\nif ((Read-Host '위 변경을 실행하려면 YES 입력') -cne 'YES') { Write-Host '취소됨'; exit 0 }\nNew-Item -ItemType Directory -Force -Path $HistoryDir | Out-Null\n$journalFile = Join-Path $HistoryDir (\"rename_{0}_{1}.json\" -f (Get-Date -Format 'yyyyMMdd_HHmmssfff'), [guid]::NewGuid().ToString('N'))\n$journal = [pscustomobject]@{ Folder=$Root; Undone=$false; Records=@() }\nSave-Journal $journal $journalFile\n$ok = 0\nforeach ($row in $plans) {\n    try {\n        $current = Get-Item -LiteralPath $row.File.FullName -ErrorAction Stop\n        if ($current.Length -ne $row.Length -or $current.LastWriteTimeUtc.Ticks -ne $row.ChangedUtc -or\n            (Test-Path -LiteralPath $row.Target)) { throw '파일이 변경됐거나 대상 이름이 이미 생겼습니다.' }\n        $record = [pscustomobject]@{ RelativeDir=$row.RelativeDir;\n            OldName=$row.File.Name; NewName=$row.NewName; State='pending';\n            Length=[long]$current.Length;\n            LastWriteUtcTicks=[long]$current.LastWriteTimeUtc.Ticks;\n            CreationUtcTicks=[long]$current.CreationTimeUtc.Ticks;\n            FileId=[PlayDockFileId]::Identify($current.FullName) }\n        $journal.Records += $record\n        Save-Journal $journal $journalFile\n        Rename-Item -LiteralPath $current.FullName -NewName $row.NewName -ErrorAction Stop\n        $record.State = 'done'; Save-Journal $journal $journalFile\n        $ok++\n    } catch {\n        Write-Warning \"이름 변경 중 실패: $($row.File.Name): $_\"\n        Write-Warning '현재까지의 변경은 되돌리기 메뉴로 복구할 수 있습니다.'\n        break\n    }\n}\nWrite-Host \"이름 변경: $ok / $($plans.Count)건. 최근 변경 되돌리기를 사용할 수 있습니다.\""
_ZERO_HASH = '0' * 64
_EXPECTED = hashlib.sha256(_PS1_SOURCE.replace('__PLAYDOCK_HASH__', _ZERO_HASH).encode('utf-8')).hexdigest()
PS1_TEMPLATE = _PS1_SOURCE.replace('__PLAYDOCK_HASH__', _EXPECTED)
PS1_TEMPLATE_SHA256 = _EXPECTED
